<h1>Danh sách sách</h1><form method="get" class="search"><input type="hidden" name="r" value="books"><input name="search" value="<?= View::escape($search) ?>" placeholder="Tên sách hoặc tác giả"><button class="button">Tìm</button></form>
<div class="grid"><?php foreach ($books as $book): ?><article class="card"><div class="cover">📚</div><div class="card-body"><h3><?= View::escape($book['title']) ?></h3><p><?= View::escape($book['author']) ?></p><strong><?= number_format((float) $book['price'], 0, ',', '.') ?> ₫</strong><p><a class="button" href="<?= BASE_URL ?>/?r=books/detail/<?= (int) $book['id'] ?>">Chi tiết</a> <a class="button secondary" href="<?= BASE_URL ?>/?r=cart/add/<?= (int) $book['id'] ?>">Thêm giỏ</a></p></div></article><?php endforeach; ?></div>
